import json,collections
from pathlib import Path
import numpy as np
from cs2_agent.strategy import candidates,inspect_sample
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'outputs/movement/strategy'
rows=json.loads((OUT/'rows.json').read_text());metrics=json.loads((OUT/'metrics.json').read_text());names=metrics['protocol']['features'];cache={}
# Refresh only reviewed, causal positions; verify training inputs and targets did not change.
for row in rows:
 demo=row['demo']
 if demo not in cache:cache[demo]=json.loads((ROOT/'data/movement/strategy'/(demo+'.json')).read_text())['rows']
 matches=[r for r in cache[demo] if r['tick']==row['tick'] and r['h']==row['h'] and r['label']==row['label']]
 if len(matches)==1:row['view']=matches[0]['view']
(OUT/'rows.json').write_text(json.dumps(rows))
rng=np.random.default_rng(314);review=[];md=['# 回防／集合／保枪：盲评表','', '用途：人工战术评审。没有展示原选手未来行为、回合结果或模型分数。请在指定 tick 暂停回放，禁止先看后续。每张地图随机抽取 3 个测试片段，含未能自动标注的片段；不依据模型信心或结果筛选。','', '统一假设：CT 在下包 2 秒后被明确告知包的坐标。没有声称还原真实语音。当前没有导航路线验证。每个选项可并列、否决，也可填写其他方案或“信息不足”。坐标辅助在地图中定位，不能代替观察清点路线。','']
for map_name in sorted({r['map'] for r in rows}):
 eligible=[i for i,r in enumerate(rows) if r['map']==map_name and r['split']=='test'];chosen=rng.choice(eligible,min(3,len(eligible)),replace=False)
 for index in chosen:
  row=rows[index];pack=candidates(dict(zip(names,row['h'][-1])));options=pack['candidates'].copy();rng.shuffle(options)
  case={'id':f'case-{len(review)+1:02d}','sample_index':int(index),'map':map_name,'demo_sha256':row['demo'],'round':row['round'],'tick':row['tick'],'view':row.get('view'),'scenario':pack['scenario'],'evidence':pack['evidence'],'history':[{ 'seconds_before':12-2*k,'features':dict(zip(names,h))} for k,h in enumerate(row['h'])],'options':options,'rating':{'preferred':None,'acceptable':[],'other':None,'confidence':None,'missing_information':[],'reason':None}}
  review.append(case);md.extend([f"## {case['id']} · {map_name} · 第 {row['round']} 回合",'',f"样本 {int(index)}，tick {row['tick']}，demo `{row['demo']}`。",'',f"CT {pack['evidence']['ct_alive']} 人，T {pack['evidence']['t_alive']} 人；假定剩余 {pack['scenario']['nominal_bomb_seconds_remaining']:.1f} 秒；自身装备价值 {pack['evidence']['own_equipment_value']:.0f}；包的直线距离 {pack['scenario']['distance_units']:.0f} 单位。",'',f"已知位置：`{json.dumps(case['view'],ensure_ascii=False)}`",''])
  for n,o in enumerate(options):md.extend([f"{n+1}. **{o['title']}**：成立条件：{'；'.join(o['conditions'])}。主要风险：{'；'.join(o['risks'])}。"])
  md.extend(['','首选／可接受的并列方案：________','', '其他方案／缺失信息／理由：________','', '路线可行性：待核验；信心（低／中／高）：________',''])
(OUT/'blind-review.json').write_text(json.dumps(review,ensure_ascii=False,indent=2),encoding='utf-8');(OUT/'战术候选-人工盲评表.md').write_text('\n'.join(md),encoding='utf-8')
counts=collections.Counter(r['reason'] for r in rows);a=metrics['abstention'];lines=['# 回防／等待集合／保枪：首轮原型报告','', '日期：2026-10-13。本机解析与训练，无付费 API 调用。','', '## 结论','', '**已经建立可运行的条件场景、行为模型、Agent 查询接口和人工盲评材料；尚未训练出可靠的战术价值判断器。** 模型超过此次简单规则的行为分类表现，但历史模型未超过当前状态模型。三个战术候选的条件由规则编写，其合理性尚待人工评审，不能把行为概率当推荐概率。','', '## 数据与信息边界','',f"77 个 demo、30 个系列、七张地图。下包后 2／8／14／20／26／32 秒采样 CT 生存玩家，得到 {len(rows)} 个窗口，其中 {metrics['labelled']} 个有可用弱标签。保留原 19／5／6 系列划分；不是新比赛上的独立测试。",'', '每个输入含 7 帧、覆盖 12 秒；逐帧自身状态、人数、队友部署距离、道具、闪光、声音范围候选和自身点亮的最近敌情。敌情记忆从本回合此前采样帧累计，过期后不以隐藏坐标刷新。普通 `player_sound` 使用事件半径，未接入枪声资源曲线和声学遮挡；声音比较使用当前历史帧的听者位置，存在最多约 2 秒的位置时间差。敌方装备、血量、隐蔽位置不进入输入。','', '**条件假设：下包 2 秒后，给 CT 提供包的真实坐标。** 这模拟明确报点，未证明原选手当时确实知道。此前历史帧中的包位置特征为零；该假设会限制向缺少报点的普通玩家场景迁移。','', '未建立区域导航图、经济跨回合规划、队内语音、动态门和有效烟火的战术可行性计算。模型使用距离代理而非可走路线；40 秒炸弹计时、250 单位/秒移动和 5/10 秒拆包在候选说明中是明确的场景假设，不是逐 demo 配置核验。不能据此断言一条路线必然赶得上。','', '## 弱标签的具体含义','', '- 向包点靠近至少 192 单位，或观察到开始拆包。','- 六秒后净位移不超过 128 单位，且到包距离变化不超过 96 单位。','- 到包距离增加至少 192 单位，且结束时距离至少 1200 单位。','', '第二类可能是架枪、交战、小范围活动，不能直接解释为等待队友；第三类也可能是绕路，不能直接解释为保枪。未使用回合输赢决定标签。未来六秒死亡、回合结束或轨迹不明确的记录不参与分类损失，因此分类测试子集有选择偏差。没有伪造人工评价。','', '| 标签或排除原因 | 数量 |','|---|---:|']
for reason,count in counts.items():lines.append(f'| {reason} | {count} |')
lines+=['', '## 训练与验证','', '每组 3 个种子，80 轮，按验证集 NLL 选检查点。当前组将当前状态重复输入同一 GRU，保持结构和参数量相同；历史组使用真实序列；无信息组去除声音和敌情字段。对照为训练先验与预先固定的人数／时间／支援距离规则。选模型只看验证集，选择结果为 current。','', '| 模型 | 弱标签准确率 | Macro F1 | NLL |','|---|---:|---:|---:|']
for arm,v in metrics['test'].items():lines.append(f"| {arm} | {v['accuracy']:.1%} | {v['macro_F1']:.3f} | {v['NLL']:.3f} |")
lines += ['',f"分类测试共 868 个有标签窗口。置信度阈值仅用验证集选取，为 {a['threshold']:.2f}；在有标签测试子集中保留 {a['test_coverage']:.1%} 的窗口，与弱标签一致率 {a['test_accuracy']:.1%}。这是几何行为一致率，不是战术正确率，也没有包含被删失的 586 个测试窗口。",'', '未对新比赛验证、未进行真人盲评、未在真实游戏中执行候选。指标以窗口统计，相关窗口不能当独立比赛；仅有六个测试系列，不宣称统计显著性。','',f"九次训练与评估约 {metrics['seconds']:.1f} 秒，PyTorch 峰值已分配显存 {metrics['peak_mb']:.1f} MiB；不含 demo 解析和驱动显存。",'', '## 可以运行的部分','', '- AgentLoop 工具 `inspect_postplant_strategy(sample_index)` 返回证据、三种候选的条件／风险／对手回应检查及行为概率；未替换网页 A/B 决策模拟。','- `experiments/movement/predict_strategy.py` 可对注册样本或自带 7×26 历史输入执行 CPU 模型推理。','- `战术候选-人工盲评表.md` 和 `blind-review.json`：每图随机 3 个片段，共 21 个，没有未来标签和模型分数。每个片段允许其他方案与信息不足，不能用未来结果倒推评判。','- `rows.json` 是研究文件，含未来弱标签；不能整份传给决策 LLM。Agent 工具只输出白名单字段。','', '## 验证与复现','', 'Node 因果测试覆盖未来／隐藏坐标、包位置披露边界、历史敌情与标签边界；Python 候选与已有环境边界测试 9 项通过。离线 CPU 与 GPU 集成推理对照 22 个样本，最大概率差 0.000201，最高概率类别全部一致；按 0.002 概率绝对差容差验证。系列隔离、21 份盲评数据不含未来标签、Agent 工具白名单均通过检查。初次使用 1e-6 的跨设备容差未通过，随后检查了更大的样本集合并记录实际差异。','', '在工作区根目录运行：','', '```powershell',"$env:PYTHONPATH='backend'",'.venv/Scripts/python.exe experiments/movement/run_strategy_extract.py','.venv/Scripts/python.exe experiments/movement/train_strategy.py','.venv/Scripts/python.exe experiments/movement/predict_strategy.py --sample-index 0 --output outputs/movement/strategy/prediction-example.json','.venv/Scripts/python.exe experiments/movement/report_strategy.py','node experiments/movement/strategy.test.cjs','```','', '## 接下来真正缺什么','', '先完成候选的人工排序并标注理由，检查弱行为标签与实际意图的偏差；补区域图和路线时间约束后，训练候选排序器，与规则及检索对照。建立新的、尚未查看的比赛评估集，再验证历史信息与地图结构是否有益。要评价“选择后会更好”，还需要可信的受控环境试验或独立专家评价；当前结果不支持自动向玩家下结论。','']
(OUT/'回防集合保枪-首轮原型报告.md').write_text('\n'.join(lines),encoding='utf-8')
